-- =====================================================================
-- FREIGHTCON update 2026-11-13r - package 2: master clauses library
-- * master library = the general clause library (view master_clauses_library)
-- * lists per level: one-off defaults (clause_library.oneoff_list), client defaults
--   (customer_clauses) and policy defaults (policy_clauses); enabled = active
--   (pre-ticked), not enabled = standby; removing from a list never deletes the clause
-- * new categories: subject-matter insured, special cargoes, expenses, contingency,
--   claims, administration; air-only clauses
-- * seed: 67 standby clauses from the Bertling open policy, the Editor.pdf standard
--   blocks (opening, general conditions, sanctions, disclaimer) and 6 Editor wordings
-- Run after update_2026-11-13q.sql. Safe to run more than once.
-- =====================================================================

alter table public.clause_library drop constraint if exists clause_library_category_check;
alter table public.clause_library add constraint clause_library_category_check check (category in
  ('header','general','subject_matter','special_cargo','special','expenses','contingency','claims','administration','sanctions','pricing','disclaimer','subjectivity'));
alter table public.clause_library add column if not exists oneoff_list boolean not null default true;
alter table public.clause_library add column if not exists air_only boolean not null default false;
alter table public.clause_library add column if not exists source text;
alter table public.customer_clauses add column if not exists sort int not null default 100;
alter table public.policy_clauses add column if not exists sort int not null default 100;

create or replace view public.master_clauses_library as
  select id, category, title, body, maritime, air_only, active, sort, source, default_spot as oneoff_active, oneoff_list
    from public.clause_library where scope_type = 'one_off_general';
grant select on public.master_clauses_library to authenticated;

-- how many lists use a clause (warning before a library edit / delete)
create or replace function public.admin_clause_usage(p_id bigint) returns jsonb
language sql stable security definer set search_path = public as $$
  select case when not public.is_admin() then null else jsonb_build_object(
    'oneoff', (select oneoff_list from public.clause_library where id = p_id),
    'customers', (select count(*) from public.customer_clauses where clause_id = p_id),
    'policies', (select count(*) from public.policy_clauses where clause_id = p_id),
    'quotations', (select count(*) from public.quotations q, public.clause_library c where c.id = p_id and q.data->>'doc' like '%' || left(c.body, 60) || '%')) end
$$;
grant execute on function public.admin_clause_usage(bigint) to authenticated;

-- ---------- seed: library ----------
insert into public.clause_library(scope_type, scope_id, category, title, body, maritime, air_only, default_spot, oneoff_list, active, sort, source) values

  ('one_off_general', null, 'subject_matter', 'SUBJECT-MATTER INSURED (Goods, Cargoes, Merchandise)', 'On goods &/or merchandise of every description &/or all other interests incidental to the Policyholder''s business or for which the Policyholder is responsible or in respect of which the Policyholder receives instructions or authority to insure including increased value on arrival by reason of liability for and for payment of freight &/or duty &/or other charges.', false, false, false, false, true, 110, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'subject_matter', 'EXCLUDED GOODS &/OR MERCHANDISE', 'Unless otherwise agreed before commencement of risk, the following cargo &/or merchandise is excluded: Fresh food, live animals, flowers, plants, cigarettes, artwork &/or antiques, drugs, explosives, eggs, securities and other negotiable papers, jewellery, precious stones and metals, marble, granite or limestone slabs, laptop computers, computer memory chips and mobile phones.', false, false, false, false, true, 120, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'subject_matter', 'APPROVED CARGOES / GENERAL MERCHANDISE DEFINITION', 'Goods &/or Merchandise that attract no special hazard with regard to stowage, handling, packing or during normal methods of transit or by their inherent nature are not normally susceptible to losses or damage arising from pilferage, leakage, shortage, loss in weight, breakage, scratching, bruising, denting, bending or crushing or are not liable to perish, deteriorate or suffer any change in quality or suffer from electrical, mechanical or any other form of derangement or breakdown. Unless otherwise agreed before commencement of risk: approved cargoes are insured against all risks of physical loss or damage from any external cause whatsoever, irrespective of percentage, subject to Institute Cargo Clauses (A) CL382 (01/01/2009).', false, false, false, false, true, 130, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'subject_matter', 'NEW GOODS &/OR MERCHANDISE', 'Against all risks of physical loss or damage from any external cause whatsoever, irrespective of percentage, subject to Institute Cargo Clauses (A) CL382 (01/01/2009) and subject to the Institute Replacement Clause CL372 (01/12/2008) as contained herein. Upon request of the Assured and subject to declaration to the Insurers hereon, prior to attachment and before any known or reported loss or accident cover may be limited to loss of or damage to the subject-matter insured reasonably attributable to fire or explosion, vessel or craft being stranded grounded sunk or capsized, overturning or derailment of land conveyance, collision or contact of vessel craft or conveyance with any external object other than water, discharge of cargo at a port of distress, loss or damage to the subject-matter insured caused by general average sacrifice, jettison &/or washed or lost overboard, subject to the Institute Cargo Clauses (C) CL384 (01/01/2009). For shipments by air this insurance also covers loss of or damage to the subject-matter insured reasonably attributable to crash of aircraft, fire, lightning or explosion, collision, forced landing, jettison or throwing overboard for the safety of the aircraft, crew or passengers.', false, false, false, false, true, 140, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'subject_matter', 'USED GOODS &/OR MERCHANDISE', 'Unless otherwise agreed before commencement of risk: Against all risks of physical loss or damage from any external cause whatsoever, irrespective of percentage, subject to Institute Cargo Clauses (A) CL382 (01/01/2009) but excluding rust, oxidation, discoloration, marring, chipping, denting, scratching, electrical and mechanical derangement and subject to the Institute Replacement Clause - Obsolete Parts Endorsement JC2008/023 (01/12/2008) as contained herein.', false, false, false, false, true, 150, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'subject_matter', 'GOODS &/OR MERCHANDISE DESPATCHED UNPACKED', 'Unless otherwise agreed before commencement of risk: Against all risks of physical loss or damage from any external cause whatsoever, irrespective of percentage, subject to Institute Cargo Clauses (A) CL382 (01/01/2009) but excluding rust, oxidation, discoloration, scratches and chipping to paintwork &/or surface.', false, false, false, false, true, 160, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special_cargo', 'Automobiles, Lorries (Trucks), mobile Construction Site Machines incl. Cranes &/or Motor Cycles - NEW', 'Unless otherwise agreed before commencement of risk: Against all risks of physical loss or damage from any external cause whatsoever, subject to Institute Cargo Clauses (A) CL382 (01/01/2009) and subject to the Institute Replacement Clause CL372 (01/12/2008) as contained herein, but each claim shall be subject to a deductible of 2 % of the total insured value but with a minimum of USD 250 for automobiles &/or motor cycles and a minimum of USD 500/maximum of USD 5,000 for lorries &/or construction site machines for all claims other than those which are recoverable under the Institute Cargo Clauses (C) CL384 (01/01/2009) including war, strikes, riots and civil commotions. No cover shall be granted hereunder while the vehicle is being operated under its own power, except while driven on or off the carrying conveyance for purposes of positioning, loading and unloading. Spare parts, tools et al. which are not fixed to the body of the vehicle by means of screws, rivets or welding or the likewise are not covered against theft, pilferage, non-delivery. Excluding electrical &/or electronic derangement, unless caused by external impact. Excluding damage to tyres, unless the whole vehicle is affected by damage.', false, false, false, false, true, 170, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special_cargo', 'Automobiles, Lorries (Trucks) &/or mobile Construction Site Machines incl. Cranes - USED', 'The insurance is subject to an EXCEPTION REPORT AND INVENTORY issued by an independent inspection company &/or surveyor. Unless otherwise agreed before commencement of risk: Against all risks of physical loss or damage from any external cause whatsoever, subject to Institute Cargo Clauses (A) CL382 (01/01/2009), however each claim shall be subject to a deductible of 3% of the total insured value but with a minimum of USD 400 for automobiles and a minimum of USD 750/maximum of USD 7,500 for lorries &/or construction site machines for all claims other than those which are recoverable under the Institute Cargo Clauses (C) CL384 (01/01/2009) including war, strikes, riots and civil commotions. No cover shall be granted hereunder while the vehicle is being operated under its own power, except while driven on or off the carrying conveyance for purposes of positioning, loading and unloading. Spare parts, tools et al. which are not fixed to the body of the vehicle by means of screws, rivets or welding or the likewise are not covered against theft, pilferage, non-delivery. Excluding frost damage. Excluding mechanical &/or electrical &/or electronic derangement unless caused by external impact to vehicle. Excluding damage to tyres, unless the whole vehicle is affected by damage. All claims are subject to the Institute Replacement Clause - Obsolete Parts Endorsement JC2008/023 (01/12/2008) as contained herein.', false, false, false, false, true, 180, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special_cargo', 'Bagged Goods &/or Merchandise', 'Unless otherwise agreed before commencement of risk: Against all risks of physical loss or damage from any external cause whatsoever, subject to Institute Cargo Clauses (A) CL382 (01/01/2009), however claims due to breaking, tearing, bursting or ripping of the bags shall be subject to a deductible of 3 % of the insured value per bag or 0.5 % of the insured value per container resp. on the whole in case of a conventional shipment, whichever is most favourable to the Assured, but with a minimum of USD 250 for all claims other than those which are recoverable under the Institute Cargo Clauses (C) CL384 (01/01/2009) including war, strikes, riots and civil commotions.', false, false, false, false, true, 190, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special_cargo', 'Boats Not Exceeding USD 500,000 value &/or Length of 40'' resp. 12 m - NEW', 'Against all risks of physical loss or damage from any external cause whatsoever, subject to Institute Cargo Clauses (A) CL382 (01/01/2009) and subject to the Institute Replacement Clause CL372 (01/12/2008) as contained herein, however each claim shall be subject to a deductible of 1 % of the total insured value but with a minimum of USD 250 for all claims other than those which are recoverable under the Institute Cargo Clauses (C) CL384 (01/01/2009) including war, strikes, riots and civil commotions. No cover shall apply for theft, pilferage &/or non-delivery of spare parts, tools et al. which are not fixed to the hull by means of screws, rivets or the likewise. Conditions for bigger &/or more expensive boats &/or yachts to be agreed before commencement of risk. Conditions for other boats &/or yachts to be agreed before commencement of risk.', false, false, false, false, true, 200, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special_cargo', 'Bulk Cargo (2009 Open Policy Wording)', 'Unless otherwise agreed before commencement of risk: Against loss of or damage to the subject-matter insured reasonably attributable to fire or explosion, vessel or craft being stranded grounded sunk or capsized, overturning or derailment of land conveyance, collision or contact of vessel craft or conveyance with any external object other than water, discharge of cargo at a port of distress, loss or damage to the subject-matter insured caused by general average sacrifice, jettison &/or washed or lost overboard, subject to the Institute Cargo Clauses (C) CL384 (01/01/2009).', false, false, false, false, true, 210, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special_cargo', 'Chinaware, Glassware, Ceramic, Tiles &/or other breakable items', 'Unless otherwise agreed before commencement of risk: Against all risks of physical loss or damage from any external cause whatsoever, subject to Institute Cargo Clauses (A) CL382 (01/01/2009), however claims due to breakage shall be subject to a deductible of 5 % of the total insured value but with a minimum of USD 250 for all claims other than those which are recoverable under the Institute Cargo Clauses (C) CL384 (01/01/2009) including war, strikes, riots and civil commotions.', false, false, false, false, true, 220, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special_cargo', 'Frozen Foods &/or Merchandise', 'As per the Institute Frozen Meat Clauses (A) - 24 Hours Breakdown CL.324 (1.1.86) and with clause 8.1.2 to apply &/or Institute Frozen Food Clauses (A) CL.263 (1.1.86), as applicable. Institute Strikes Clauses (Frozen Meat) CL.326 (1.1.86) &/or Institute Strikes Clauses (Frozen Food) CL.265 (1.1.86) amended to temperature controlled, as applicable.', false, false, false, false, true, 230, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special_cargo', 'Household Goods &/or Personal Effects excluding Artwork &/or Antiques (2009 Open Policy Wording)', 'Unless otherwise agreed before commencement of risk: Against all risks of physical loss or damage from any external cause whatsoever, subject to Institute Cargo Clauses (A) CL382 (01/01/2009), however each claim shall be subject to a deductible of 3 % of the total insured value but with a minimum of USD 250 for all claims other than those which are recoverable under the Institute Cargo Clauses (C) CL384 (01/01/2009) including war, strikes, riots and civil commotions.
Warranted that fragile items such as glass, china, marble and earthenware are limited to no more than 15 % of the insured value.
It is further warranted that shipments are professionally packed and a valued itemized inventory is available to the Insurers prior to shipment.
In the event of loss of or damage to any article or articles not separately valued such loss or damage will be recoverable in the same proportion as the total amount insured on articles not separately valued bears to the total value of such articles.
Shipments of household and personal effects that are not professionally packed shall be limited to loss of or damage to the subject-matter insured reasonably attributable to perils covered under the Institute Cargo Clauses (C) CL384 (01/01/2009).
Pair & Set
Where any item consists of articles in pair or set, the Insurers will not be liable for more than the value of any particular part or parts which may be lost, without reference to any special value which such article or articles may have as part of such pair or set, and in no case to be liable for more than a proportionate part of the insured value of such pair or set.
Depreciation
The Insurers'' liability is restricted to the reasonable cost of repair and no claim will attach for depreciation consequent hereon.', false, false, false, false, true, 240, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special_cargo', 'Liquids in Tanks &/or Tank Containers (2009 Open Policy Wording)', 'Against all risks of physical loss or damage from any external cause whatsoever, subject to Institute Cargo Clauses (A) CL382 (01/01/2009), however claims due to difference/loss in weight shall be subject to a deductible of 0.5 % of the total insured value each tank or tank container, but with a minimum of USD 250 for all claims other than those which are recoverable under the Institute Cargo Clauses (C) CL 254 (01/01/2009) including war, strikes, riots and civil commotions. It is warranted that a certificate of weight is issued by an independent inspection company upon completion of loading operations.', false, false, false, false, true, 250, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special_cargo', 'Lumber &/or Timber (2009 Open Policy Wording)', 'As per Institute Timber Trade Federation Clauses CL.335 (1.4.86)
Institute Strikes Clauses (Timber Trade Federation) CL.336 (1.4.86)
However, each claim shall be subject to a deductible of 2% of the total insured value but with a minimum of USD 250 for all claims other than those which are recoverable under the Institute Cargo Clauses (C) CL384 (01/01/2009) including war, strikes, riots and civil commotions.', false, false, false, false, true, 260, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special_cargo', 'Owned Containers', 'Standard containers owned by the Policyholder, Assured or the shipper and engaged together with the cargo insured under this Open Policy may be covered as per following terms: Against all risks of physical loss or damage from any external cause whatsoever, subject to Institute Cargo Clauses (A) CL382 (01/01/2009), however each claim shall be subject to a deductible of USD 250 each occurrence and per container for all claims other than those which are recoverable under the Institute Cargo Clauses (C) CL384 (01/01/2009) including war, strikes, riots and civil commotions. No cover shall be granted hereunder for scratches and chipping to paintwork &/or surface. Excluding ordinary wear and tear. Excluding rust, oxidation and discoloration absolutely. Excluding damage to the timber planks and excluding claims as a consequence of faulty construction of the container. Insurers'' liability is restricted to the reasonable cost of repair and no claim will attach for depreciation consequent hereon. In case of total loss the current market value will be compensated. Other containers may be insured under terms to be agreed case by case.', false, false, false, false, true, 270, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special_cargo', 'Refrigerated Cargoes', 'For goods &/or merchandise transported in reefer containers this insurance shall also cover loss and/or damage (material deterioration) resulting from breakdown of refrigerating machinery/cooling unit of the container for a period of not less than 6 consecutive hours.', false, false, false, false, true, 280, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special_cargo', 'Scrap but excluding Turnings, Borings and Engine Blocks', 'Unless otherwise agreed before commencement of risk: Against loss of or damage to the subject-matter insured reasonably attributable to fire or explosion, vessel or craft being stranded grounded sunk or capsized, overturning or derailment of land conveyance, collision or contact of vessel craft or conveyance with any external object other than water, discharge of cargo at a port of distress, loss or damage to the subject-matter insured caused by general average sacrifice, jettison &/or washed or lost overboard, subject to the Institute Cargo Clauses (C) CL384 (01/01/2009). Conditions for Turnings, Borings and Engine Blocks to be agreed before commencement of risk.', false, false, false, false, true, 290, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special_cargo', 'Steel and Steel Products (2009 Open Policy Wording)', 'Provided that shipments take place in box containers: Against all risks of physical loss or damage from any external cause whatsoever, irrespective of percentage, subject to Institute Cargo Clauses (A) CL382 (01/01/2009) but excluding rust, oxidation and discoloration, unless caused by direct contact with salt water &/or aggressive chemicals. If shipments are not in box containers conditions have to be agreed before commencement of risk.', false, false, false, false, true, 300, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special_cargo', 'Steel Pipes (2009 Open Policy Wording)', 'Unless otherwise agreed before commencement of risk: Against all risks of physical loss or damage from any external cause whatsoever, irrespective of percentage, subject to Institute Cargo Clauses (A) CL382 (01/01/2009), but excluding rust, oxidation and discoloration, unless caused by direct contact with salt water &/or aggressive chemicals and excluding the risks of bending, twisting and end damage. If agreed before commencement of risk: Against all risks of physical loss or damage from any external cause whatsoever, irrespective of percentage, subject to Institute Cargo Clauses (A) CL382 (01/01/2009), but excluding rust, oxidation and discoloration, unless caused by direct contact with salt water &/or aggressive chemicals. It is warranted that loading and discharge surveys are carried out for loss prevention reasons by independent experts. Further subject to the CUTTING CLAUSE as contained herein (see SPECIAL CONDITIONS).', false, false, false, false, true, 310, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special_cargo', 'Wines, Beers, Liquors and Similar Spirits', 'Against all risks of physical loss or damage from any external cause whatsoever, subject to Institute Cargo Clauses (A) CL382 (01/01/2009), however claims due to pilferage and breakage shall be subject to a deductible of 5 % of the total insured value, but with a minimum of USD 250 for all claims other than those which are recoverable under the Institute Cargo Clauses (C) CL384 (01/01/2009) including war, strikes, riots and civil commotions.', false, false, false, false, true, 320, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special_cargo', 'Windows, Plates Glass and Similar Merchandise', 'Unless otherwise agreed before commencement of risk: Against loss of or damage to the subject-matter insured reasonably attributable to fire or explosion, vessel or craft being stranded grounded sunk or capsized, overturning or derailment of land conveyance, collision or contact of vessel craft or conveyance with any external object other than water, discharge of cargo at a port of distress, loss or damage to the subject-matter insured caused by general average sacrifice, jettison &/or washed or lost overboard, subject to the Institute Cargo Clauses (C) CL384 (01/01/2009).', false, false, false, false, true, 330, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special', 'Additional Cargo', 'With liberty for vessels which have loaded cargo for two or more ports subsequently to take on further cargo or cargoes for discharge at any destination either before or after discharge of first or subsequent cargoes.', false, false, false, false, true, 340, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special', 'Brands', 'In case of damage to property bearing a brand, the salvage value of such damaged property shall be determined after removal of all brands and trade marks (on containers on which brand cannot be removed, contents to be transferred to plain bulk containers) which might be taken to indicate that the guarantee or brand of the manufacturer or Assured attached to the said property. The Insurers waive their right to take over any merchandise or containers from which it is impractical to destroy all evidence of the brand or trade marks connection therewith, such merchandise or containers to be destroyed.', false, false, false, false, true, 350, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special', 'Both to blame Collision Clause', 'Irrespective of the sum insured this insurance covers any contribution in full for which the Assured is legally liable under a "Both to blame Collision Clause" arising from a contract of affreightment.', false, false, false, false, true, 360, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special', '"Claused" Bill of Lading', 'This insurance is not to be prejudiced solely by reason of the marking of the bill of lading, or similar document, with a clause indicating the subject-matter insured being insufficiently packed.', false, false, false, false, true, 370, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special', 'Communicable Disease Exclusion (Cargo) - JC2020-011 17 April 2020 (Full Wording)', '1. Notwithstanding any provision to the contrary within this insurance, this insurance does not insure any loss, damage, liability, claim, cost or expense of whatsoever nature caused by, contributed to by, resulting from, arising out of, or in connection with a Communicable Disease or the fear or threat (whether actual or perceived) of a Communicable Disease regardless of any other cause or event contributing concurrently or in any other sequence thereto.
2. As used herein, a Communicable Disease means any disease which can be transmitted by means of any substance or agent from any organism to another organism where:
2.1. the substance or agent includes, but is not limited to, a virus, bacterium, parasite or other organism or any variation thereof, whether deemed living or not, and
2.2. the method of transmission, whether direct or indirect, includes but is not limited to, airborne transmission, bodily fluid transmission, transmission from or to any surface or object, solid, liquid or gas or between organisms, and
2.3. the disease, substance or agent can cause or threaten bodily injury, illness, damage to human health, human welfare or property.', false, false, false, false, true, 380, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special', 'Concealed Damage', 'It is agreed that any loss or damage discovered on opening cases, containers or packages, shall be deemed to have occurred during transit insured hereunder and irrespective of attachment of Assured''s Interest and shall be paid accordingly unless conclusive proof to the contrary be established. Cases, containers or packages showing outward signs of loss &/or damage are to be opened immediately on arrival. This clause shall only apply up to 60 days after arrival at the place of destination.', false, false, false, false, true, 390, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special', 'Container Fitness', 'Notwithstanding anything contained herein to the contrary where cargo, insured hereunder, is carried in containers, it is agreed, as between the Assured and the Insurers, that the seaworthiness &/or cargo-worthiness of the container is hereby admitted.', false, false, false, false, true, 400, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special', 'Cutting Clause for Steel Pipes', 'In the event of a claim for breakage, chipping, cracking, bending, denting or any other damage provided this be of such a nature that it is practicable to use the sound portion or portions for the purpose for which they were originally intended the Insurers to pay proportionate value of the part cut off together with the costs of cutting and to receive any salvage on such proportion.', false, false, false, false, true, 410, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special', 'Deliberate Damage - Pollution Hazard', 'This insurance is extended to cover, but only while the subject matter insured is on a waterborne conveyance, loss or damage to said property directly caused by Governmental authorities acting for the public welfare to prevent or mitigate a pollution hazard or threat thereof, provided that the accident or occurrence creating the situation which required such Governmental action would have resulted in a recoverable claim under this policy (subject to all of its terms, clauses, conditions and warranties) if the subject matter insured would have sustained physical loss or damage as a direct result of such accident or occurrence.', false, false, false, false, true, 420, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special', 'Diverted Cargoes', 'In the event of goods &/or merchandise being sold to outside buyers on the water and diverted as necessary, such goods &/or merchandise shall be covered hereunder retrospectively from loading on the conditions required by the buyer but in no event wider than the coverage provided hereon and insurance certificates issued accordingly. Where the goods &/or merchandise which have been shipped for sale to an outside buyer and are diverted for whatever reason for delivery to another outside buyer to whom there is an obligation to provide different insuring conditions but in no event wider than the cover provided hereon to the original sale it is agreed the amended conditions apply retrospectively from loading.', false, false, false, false, true, 430, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special', 'Dock Strikes or Labour Disputes', 'In the event of shipments being delayed or diverted due to dock strikes or labour disputes, the Insurers agree to hold covered at a premium to be arranged pending the receipt of the relevant details.', false, false, false, false, true, 440, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special', 'F.O.B/F.A.S. Sales', 'This insurance is extended to cover shipments sold by the Assured F.O.B &/or F.A.S &/or on similar terms. Such cover shall attach from the time of leaving the store, warehouse, factory at interior point and shall continue whilst in transit to the port of export and while there until loaded on board the overseas vessel or until the Assured''s interest or responsibility ceases in accordance with the terms of sale, whichever shall first occur.', false, false, false, false, true, 450, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special', 'General Average Clause', 'This insurance covers general average, salvage and salvage charges, adjusted or determined according to the contract of affreightment &/or the governing law and practice (or, if there is no contract of affreightment, according to Foreign Statement or to the York-Antwerp Rules) incurred to avoid or in connection with the avoidance of loss from any cause except those specifically excluded here from. For the purpose of claims for general average contribution and salvage charges recoverable hereunder, the subject-matter insured shall be deemed to be insured for its full contributory value. General average deposits refunded in full upon presentation of original receipts. Claims for general average, salvage charges, sue and labour payable in full irrespective of percentage.', false, false, false, false, true, 460, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special', 'Hijacking', 'The cover under this insurance is extended to include physical loss of or physical damage to the goods directly or indirectly arising out of unlawful seizure or wrongful exercise or control of the carrying conveyance, vessel or aircraft (including any attempt at such seizure or control) made by any person or persons. Including the costs of re-forwarding the goods should they be landed at a place other than their scheduled destinations.', false, false, false, false, true, 470, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special', 'Inchmaree Clause', 'This insurance also covers any loss of or damage to the subject-matter insured hereunder caused by accidents in loading, discharging, or hauling of cargo or in bunkering or in taking in fuel or caused through the bursting &/or breakage &/or loose connections of boilers, pipes, shafts, or through any latent defect in the machinery, hull or appurtenances, or from faults or errors in the navigation or management of the vessel for which the vessel, her owners, agents or charterers is or are relieved of responsibility.', false, false, false, false, true, 480, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special', 'Increased Value', 'This insurance is also to cover increased value of cargo by reason of duty or other charges on arrival at port of discharge as may be required by the Assured subject to the same terms and conditions as cargo and to pay as may be paid thereon, subject to such increased value being declared hereunder.', false, false, false, false, true, 490, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special', 'Jason Clause', 'This insurance is extended to cover the Assured''s liability in respect of such form of Jason Clause (new or old) as may appear in a Bill of Lading governing relative shipments.', false, false, false, false, true, 500, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special', 'Marine Cyber Endorsement - LMA5403 11 November 2019 (Full Wording)', 'Subject only to paragraph 3 below, in no case shall this insurance cover loss, damage, liability or expense directly or indirectly caused by or contributed to by or arising from the use or operation, as a means for inflicting harm, of any computer, computer system, computer software programme, malicious code, computer virus, computer process or any other electronic system.
Subject to the conditions, limitations and exclusions of the policy to which this clause attaches, the indemnity otherwise recoverable hereunder shall not be prejudiced by the use or operation of any computer, computer system, computer software programme, computer process or any other electronic system, if such use or operation is not as a means for inflicting harm.
Where this clause is endorsed on policies covering risks of war, civil war, revolution, rebellion, insurrection, or civil strife arising therefrom, or any hostile act by or against a belligerent power, or terrorism or any person acting from a political motive, paragraph 1 shall not operate to exclude losses (which would otherwise be covered) arising from the use of any computer, computer system or computer software programme or any other electronic system in the launch and/or guidance system and/or firing mechanism of any weapon or missile.', false, false, false, false, true, 510, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special', 'Non-Containerised Cargo shipped On-Deck upon Approval by the Assured', 'Unless otherwise agreed before commencement of risk: Against loss of or damage to the subject-matter insured reasonably attributable to fire or explosion, vessel or craft being stranded grounded sunk or capsized, collision or contact of vessel craft or conveyance with any external object other than water, discharge of cargo at a port of distress, loss or damage to the subject-matter insured caused by general average sacrifice, jettison &/or washed or lost overboard, subject to the Institute Cargo Clauses (C) CL384 (01/01/2009).', false, false, false, false, true, 520, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special', 'Non-Containerised Cargo shipped On-Deck without Knowledge of the Assured', 'Against all risks of physical loss or damage from any external cause whatsoever, subject to Institute Cargo Clauses (A) CL382 (01/01/2009). This cover also applies in cases where the Assured accept a Bill of Lading with on-deck option. The Assured are obliged to inform the Insurers as soon as they become aware of this fact and the Insurers may charge an additional premium.', false, false, false, false, true, 530, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special', 'Packing Clause', 'In the event of a claim being made for loss or damage which is alleged to be caused by insufficient or unsuitability of packing or preparation of the subject matter insured, the Insurers hereby agree that they will not use such alleged insufficiency or unsuitability as a defence against the claim in any case where packing or preparation was carried out by a party other than the Assured and the insufficiency or unsuitability arise entirely without the Assured''s privity or knowledge. For the purpose of this clause "packing" shall be deemed to include stowage in a container &/or other similar methods of unit load. It is further agreed that where packing or preparation is undertaken by the Assured, the Insurers accept such packing or preparation as sufficient or suitable to protect subject-matter insured against loss or damage and further agree to waive rights of subrogation against the Assured. This agreement is not to interfere with rights of subrogation against sellers &/or packers &/or other responsible third parties &/or their insurers, furthermore the Assured agrees to assist the Insurers in all respects to pursue rights of recovery.', false, false, false, false, true, 540, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special', 'Process', 'The Insurers will not pay for any loss or damage to the subject matter insured, which is due to or directly results from any process of use, work-on, testing or repair.', false, false, false, false, true, 550, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special', 'Returned or Refused Shipments Clause', 'This insurance is to cover all shipments, subject to the original insuring conditions, which may be refused at the time of delivery and returned by the consignee &/or consignees, while awaiting shipment or reshipment and until received by the Assured or otherwise disposed of.', false, false, false, false, true, 560, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special', 'Seals Intact', 'In respect of shipments in containers, curtain-sided trailers or full vehicle loads, provided documentary evidence is produced to substantiate the quantity loaded into a container, trailer or vehicle, the fact that the container, trailer or vehicle''s seal is intact at the point of unloading shall not invalidate claims for theft, pilferage, shortage and non-delivery.', false, false, false, false, true, 570, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special', 'Short Landing Claims', 'It is agreed that settlement of claims for short landing shall not be delayed pending receipt by the insurers of short landing certificate &/or evidence of irretrievable loss.', false, false, false, false, true, 580, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special', 'Sue And Labour', 'In case of any imminent or actual loss or misfortune it shall be lawful and necessary to and for the Assured, his or their factors, servants and assigns, to sue and labour and travel for, in and about the defence, safeguard and recovery of the goods and merchandises, or any part thereof, without prejudice to this insurance, nor shall the acts of the Assured or the Insurers in recovering, saving and preserving the property insured, in case of disaster, be considered a waiver or an acceptance of abandonment; to the charges whereof, the Insurers will contribute according to the rate and quantity of the sum herein insured.', false, false, false, false, true, 590, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special', 'Voyage Clause', 'Notwithstanding the provisions of the Institute Cargo Clauses (A) CL382 (01/01/2009), article 8, the insurance hereunder attaches from the time the subject-matter is picked up for the purpose of loading of a conveyance and continues whilst the subject-matter is in transit, &/or in store or elsewhere in the course of transit, &/or at consolidation or deconsolidation points and until finally delivered to final destination. Including risks in Customs as required, and transhipments, craft and barge risks, whether customary or otherwise. Including during delays within or beyond the Assured''s control and including whilst held as stock (onshore or offshore) &/or interest held for the purpose of processing. Further including the risks of loading prior to dispatch and unloading after arrival at Assured''s or consignee''s or consignor''s premises and in the case of containers, during the stuffing and un-stuffing thereof.', false, false, false, false, true, 600, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special', 'Waiver of Recourse Rights - Charterer/Operator', 'In cases where the Policyholder is charterer or owner or operator of vessel(s) carrying goods covered under this contract, the Insurers agree to waive their rights of recourse against the ship &/or ship-owners &/or ship manager if and insofar as the Policyholder has to hold harmless such ship &/or ship-owners &/or ship manager for any such claim upon cargo Insurers. The Insurers also agree to waive their rights of recourse against the Policyholder as owner, operator and manager of discharge installations for any loss of cargo arising out of such installations or its ancillary equipment.', false, false, false, false, true, 610, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special', 'Waiver of Subrogation &/or Recourse Rights - Forwarder', 'The Insurers agree to waive all their rights of subrogation and/or recourse against the Policyholder or any of the Policyholder''s associated or subsidiary companies in the course of their business as freight forwarders. Excepted are acts of gross negligence of the directors of the Policyholder or any of the Policyholder''s associated or subsidiary companies. Measures taken by the Policyholder or the Insurers with the object of saving, protecting or recovering the subject-matter insured shall not be considered as a waiver or acceptance of abandonment or otherwise prejudice rights of either party.', false, false, false, false, true, 620, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special', 'Waiver or Release', 'This Policy shall not be invalidated by the Assured''s acceptance of a waiver or release of liability contained in a contract of carriage, charter party, bill of lading, waybill or receipt from any carrier or receipt from any owner or operator of any vessel, terminal or storage facility. However, this regulation will not operate unless the acceptance is made innocently and prior to the Assured becoming aware of any occurrence of loss or damage to which the waiver or release applies.', false, false, false, false, true, 630, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special', 'Warehouse - Breakdown of Heating &/or Cooling', 'This insurance also to cover loss of or damage to the subject-matter insured while contained in approved warehouses caused by interruption of power or change of temperature resulting from, the total or partial destruction or disablement by fire or lightning of the power, heating, cooling or refrigerating apparatus, including all connections or supply pipes in said building(s) caused by physical damage resulting from an insured peril to said building(s) or equipment therein, or any of the building(s), furnishing power, heat or refrigeration.', false, false, false, false, true, 640, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special', 'Wilful Misconduct', 'Notwithstanding anything to the contrary contained elsewhere herein or in the law and practice to which this policy is subject, this insurance shall not exclude loss damage or expense attributable to wilful misconduct of any person or persons committed without the privity of the directors &/or officers of the Assured.', false, false, false, false, true, 650, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'expenses', 'Extra Expenses for Interruption of Transport', 'Notwithstanding anything herein to the contrary this insurance is also to indemnify the Insured for up to USD 100,000 each and every loss and in the aggregate per annum in respect of additional expenses incurred by the Insured in attempting to prosecute an intended voyage covered hereunder whether such attempt may ultimately prove successful or otherwise (including but not limited to extra chartering costs &/or storage costs &/or transhipment costs &/or guarantees and all other forwarding costs) as a result of one or more of the following occurrences: (1) the vessel &/or conveyance on which the cargo is being carried being arrested, restrained, detained &/or otherwise delayed for any time period and as a result of any reason whatsoever, excluding however financial default &/or insolvency of the Assured; (2) the cargo being forcibly discharged from the vessel &/or conveyance as a result of any reason whatsoever, excluding however financial default &/or insolvency of the Assured; (3) loss of, mechanical breakdown of, or damage to the hull, machinery (including electrical machinery and boilers) &/or equipment of the vessel &/or conveyance on which the cargo is being carried. The cover afforded hereunder is in addition to the sum insured &/or limits of liability provided elsewhere within this insurance. Provided always that at the time of the loading of the cargo on board the vessel the Assured, their agents or servants are not aware of any information which may lead to an inference of the possibility of such insolvency or financial default of the aforesaid parties and shall take all reasonable and prudent measures to establish the financial reliability and integrity of the aforesaid parties.', false, false, false, false, true, 660, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'expenses', 'Relocation Expenses', 'This insurance is extended to cover, in addition to any other amount recoverable under this insurance, extra expenses reasonably incurred by the Assured in the relocation, modification or protection of other property necessary in order to restore or protect the insured goods following an insured loss. Relocation and protection costs in particular are expenses for the disassembly or reassembly of machines, for breaking through, demolishing or reconstructing parts of a building, or for widening openings. This insurance excludes absolutely any expenses incurred in the prevention or elimination of damage to the environment, in particular to air, water or soil. The Insurers are liable only to the extent that compensation is not available under another insurance policy. The Insurers are not subrogated to the rights of the Assured in respect of the goods damaged or lost following any indemnification for expenses and costs incurred. Furthermore, the Insurers accept no liability arising out of the existence of goods damaged or lost. The maximum liability under this extension shall be the lesser of either: USD 100,000, or 20% of the proportionate insured value under this policy of the damaged subject-matter removed, in respect of any one occurrence or series of occurrences arising out of any one event.', false, false, false, false, true, 670, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'expenses', 'Debris Removal Expenses', 'This insurance is extended to cover, in addition to any other amount recoverable under this insurance, extra expenses reasonably incurred by the Assured for the salvage/removal/disposal/destruction of the subject-matter insured, or part thereof, by reason of damage thereto caused by an insured peril, but excluding absolutely any expenses incurred in consequence of or to prevent or mitigate pollution or contamination, or any threat or liability thereof and the cost of removal of any cargo from any vessel or craft. This insurance shall also cover cost paid by the Assured to Governmental authorities due to their removing or destruction of the undamaged parts of the subject-matter insured. The maximum liability under this extension shall be the lesser of either: USD 3,000,000, or 20% of the proportionate insured value under this policy of the damaged subject-matter removed, in respect of any one occurrence or series of occurrences arising out of any one event.', false, false, false, false, true, 680, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'expenses', 'Air Freight Charges', 'In the event of loss of or damage to goods hereunder the Insurers shall either pay the costs of: returning by air freight damaged goods to manufacturers and/or suppliers for repair; or air freight and replacement goods from manufacturers and/or suppliers to destination, notwithstanding the goods lost or damaged were not originally despatched by air freight. The maximum liability under this extension shall be the lesser of either: USD 50,000, or 25% of the insured value, in respect of any one occurrence or series of occurrences arising out of any one event.', false, false, false, false, true, 690, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'expenses', 'Overtime Expenses', 'In the event of loss of or damage to goods hereunder the Insurers shall pay extraordinary costs caused by overtime, night-shift, Sunday or holiday premiums etc. in order to get the subject-matter insured repaired in due time. The maximum liability under this extension shall be the lesser of either: USD 50,000, or 25% of the insured value, in respect of any one occurrence or series of occurrences arising out of any one event.', false, false, false, false, true, 700, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'expenses', 'Re-Packing Expenses', 'The costs of re-packing, re-bundling, re-bagging, re-cartoning &/or re-palletizing shall be for the account of Insurers regardless whether the insured interest has sustained damage or not even if such cost is incurred at the final destination.', false, false, false, false, true, 710, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'expenses', 'Re-Labelling Expenses', 'Including the cost of re-labelling and re-packing should labels &/or packs be damaged irrespective of whether there is any damage to the contents following a peril insured.', false, false, false, false, true, 720, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'expenses', 'Fumigation', 'The Insurers shall pay the cost of fumigating cargo, but excluding damage or depreciation caused by such fumigation except as provided in this stipulation. The Assured warrants that there is no compulsory order in being or published at the time of the commencement of the voyage/transit requiring fumigation. In the event of loss or damage to the subject matter insured caused by fumigation by order of a properly constituted authority, the Insurers agree to indemnify the Assured for such loss or damage, and the Assured agree to subrogate these Insurers any recourse they may have for recovery of such loss or damage from third parties. The maximum liability under this extension shall be the lesser of either: USD 50,000, or 25% of the insured value, in respect of any one occurrence or series of occurrences arising out of any one event.', false, false, false, false, true, 730, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'expenses', 'Segregation Expenses', 'If, following a loss recoverable under this policy, it is necessary for the Assured, in order to avert or minimise further loss or damage &/or in proving quantum for the claim, to sort or segregate damaged from undamaged subject matter insured, then the Insurers will pay for the necessary, extraordinary and reasonable costs incurred in so doing. The maximum liability under this extension shall be the lesser of either: USD 25,000, or 25% of the insured value, in respect of any one occurrence or series of occurrences arising out of any one event.', false, false, false, false, true, 740, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'contingency', 'Buyer''s Interest Clause (Contingency Insurance)', 'Buyer''s Interest Clause for goods purchased on a CIF basis or on similar terms: If agreed before commencement of risk and where the goods are purchased by the Assured on a CIF basis or on insured or delivered terms where the Assured are not responsible for insurance and the supplier or consignor fails to effect insurance or effects an insurance which is subsequently rendered inoperative or which is more restricted than the protection afforded hereunder then such goods shall be covered on the normal cover conditions. The Insurers will be subrogated to all rights and remedies of the Assured against the supplier &/or the suppliers Insurers &/or other parties and in no case shall this insurance contribute in double insurance. It is a condition precedent to liability under this clause that this insurance not to be divulged to the seller.', false, false, false, false, true, 750, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'contingency', 'Seller''s Interest Clause (Contingency Insurance)', 'Seller''s Interest Clause for goods sold FOB or CFR or similar terms: If agreed before commencement of risk and where the goods are sold by the Assured on FOB or CFR or on similar terms and the receiver or consignee fails to effect insurance or effects an insurance which is subsequently rendered inoperative or which is more restricted than the protection afforded hereunder, such goods shall be covered hereunder on the normal cover conditions. The Insurers will be subrogated to all rights and remedies of the Assured against the receiver or consignee or their Insurers &/or other parties and in no case shall this insurance contribute in double insurance. It is a condition precedent to liability under this clause that this insurance not to be divulged to the buyer. Any assignment of this policy or any other interest or claim hereunder shall discharge the Insurers from all liability whatsoever. Should the Assured become aware that the consignee has failed to take up goods or documents or both and advises the Insurers promptly, then this insurance is converted to a primary one subject to contract terms and conditions on behalf of the Assured and shall remain in until such time as the goods are either finally taken up or otherwise disposed of, including reshipment. Excluding claims hereon by reason of Government action &/or regulations preventing transfer of currency.', false, false, false, false, true, 760, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'contingency', 'Letter of Credit Insurance Requirements', 'It is noted and agreed hereon that the Insurers are to allow the Policyholder to issue certificates of insurance on terms and conditions as may be required for letter of credit purposes, but in any event no wider than all risks of physical loss &/or damage. In the event of loss claims will only be recoverable under the terms and conditions of the Open Policy hereunder and will not cover losses which may fall between cover terms and conditions and those required for letter of credit purposes. Notwithstanding anything to the contrary it is further noted and agreed that if the Assured require to be covered on such shipments the Insurers agree to hold covered subject to prior advice and at an additional premium to be agreed.', false, false, false, false, true, 770, 'Bertling Open Policy 2009'),
  ('one_off_general', null, 'special_cargo', 'Household Goods &/or Personal Effects (Editor wording 1982)', 'Against all risks of physical loss or damage from any external cause whatsoever, subject to Institute Cargo Clauses (A) CL.252 (1.1.82), however each claim shall be subject to a deductible of 3% of the total insured value but with a minimum of USD 250 for all claims other than those which are recoverable under the Institute Cargo Clauses (C) CL.254 (1.1.82) including war, strikes, riots and civil commotions.
Warranted that fragile items such as glass, china, marble and earthenware are limited to no more than 15% of the insured value.
It is further warranted that shipments are professionally packed and a valued itemized inventory is available to Underwriters.
In the event of loss of or damage to any article or articles not separately valued such loss or damage will be recoverable in the same proportion as the total amount insured on articles not separately valued bears to the total value of such articles.
Shipments of household and personal effects that are not professionally packed shall be limited to loss of or damage to the subject-matter insured reasonably attributable to perils covered under the Institute Cargo Clauses (C) CL.254 (1.1.82).

Pair & Set Clause
Where any item consists of articles in pair or set, Underwriters will not be liable for more than the value of any particular part or parts which may be lost, without reference to any special value which such article or articles may have as part of such pair or set, and in no case to be liable for more than a proportionate part of the insured value of such pair or set.

Depreciation
Underwriters'' liability is restricted to the reasonable cost of repair and no claim will attach for depreciation consequent hereon.', false, false, false, false, true, 2000, 'Editor.pdf'),
  ('one_off_general', null, 'special_cargo', 'Liquids in Tanks &/or Tank Containers (Editor wording 1982)', 'Against all risks of physical loss or damage from any external cause whatsoever, subject to Institute Cargo Clauses (A) CL.252 (1.1.82), however claims due to difference/loss in weight shall be subject to a deductible of 0.5% of the total insured value each tank or tank container, but with a minimum of USD 250 for all claims other than those which are recoverable under the Institute Cargo Clauses (C) CL 254 (1.1.82) including war, strikes, riots and civil commotions. It is warranted that a certificate of weight is issued by an independent inspection company upon completion of loading operations.', false, false, false, false, true, 2010, 'Editor.pdf'),
  ('one_off_general', null, 'special_cargo', 'Lumber &/or Timber (Editor wording 1982)', 'As per the Institute Timber Trade Federation Clauses CL.335 (1.4.86) Institute War Clauses (Cargo) CL.255 (1.1.82) Institute Strikes Clauses (Timber Trade Federation) CL.336 (1.4.86)
However each claim shall be subject to a deductible of 2% of the total insured value but with a minimum of USD 250 for all claims other than those which are recoverable under the Institute Cargo Clauses (C) CL.254 (1.1.82) including war, strikes, riots and civil commotions.', false, false, false, false, true, 2020, 'Editor.pdf'),
  ('one_off_general', null, 'special_cargo', 'Bulk Cargo (Editor wording 1982)', 'Unless otherwise agreed before commencement of risk:
Against loss of or damage to the subject-matter insured reasonably attributable to fire or explosion, vessel or craft being stranded grounded sunk or capsized, overturning or derailment of land conveyance, collision or contact of vessel craft or conveyance with any external object other than water, discharge of cargo at a port of distress, loss or damage to the subject-matter insured caused by general average sacrifice, jettison &/or washed or lost overboard, subject to the Institute Cargo Clauses (C) CL384 (01/01/2009).', false, false, false, false, true, 2030, 'Editor.pdf'),
  ('one_off_general', null, 'special_cargo', 'Steel and Steel Products (Editor wording 1982)', 'Provided that shipments take place in box containers:
Against all risks of physical loss or damage from any external cause whatsoever, irrespective of percentage, subject to Institute Cargo Clauses (A) CL.252 (1.1.82) but excluding rust, oxidation and discoloration, unless caused by direct contact with salt water. If shipments are not in box containers conditions have to be agreed before commencement of risk.', false, false, false, false, true, 2040, 'Editor.pdf'),
  ('one_off_general', null, 'special_cargo', 'Steel Pipes (Editor wording 1982)', 'Unless otherwise agreed before commencement of risk:
Against all risks of physical loss or damage from any external cause whatsoever, irrespective of percentage, subject to Institute Cargo Clauses (A) CL.252 (1.1.82), but excluding rust, oxidation and discolouration, unless caused by direct contact with salt water &/or aggressive chemicals and excluding the risks of bending, twisting and end damage.', false, false, false, false, true, 2050, 'Editor.pdf'),
  ('one_off_general', null, 'general', 'General Conditions (Open Policy 2009)', 'Applicable to all Interests
Institute Cargo Clauses (A) CL382 (01/01/2009)
Institute War Clauses (Cargo) CL385 (01/01/2009)
Institute War Cancellation Clause (Cargo) CL271 (01/12/1982)
Institute Strikes Clauses (Cargo) CL386 (01/01/2009)
Institute Classification Clause CL354 (01/01/2001) with overage additional premiums not to apply to vessels up to 20 years of age. Vessels over 20 years of age are held covered at rates and conditions to be agreed subject to prior advice to the Insurers hereon.
Termination of Transit Clause (Terrorism) 2009 JC2009/056 (01/01/2009)
Cargo ISM Endorsement JC98/019 (01/05/1998)
Cargo ISM Forwarding Charges Clause JC98/023 (04/06/1998) at no additional premium
Cargo ISPS Endorsement JC2004/050 (04/11/2004)
Cargo ISPS Forwarding Charges Clause JC2004/050b (04/11/2004) at no additional premium
Institute Radioactive Contamination, Chemical, Biological, Bio-Chemical, Electromagnetic Weapons Exclusion Clause CL370 (10/11/2003)
Institute Replacement Clause CL372 (01/12/2008)
Institute Replacement Clause - Obsolete Parts Endorsement JC2008/023 (01/12/2008)
Cargo Accumulation Clause JC2012/010 (21/12/2012)
Communicable Disease Exclusion (Cargo) JC2020-011 (17/04/2020)
Marine Cyber Endorsement LMA5403 (11/11/2019)', false, false, false, false, true, 5, 'Editor.pdf'),
  ('one_off_general', null, 'general', 'Air / postal clauses', 'Institute Cargo Clauses (Air) CL387 (01/01/2009)
Institute War Clauses (Air Cargo) CL388 (01/01/2009)
Institute Strikes Clauses (Air Cargo) CL389 (01/01/2009)
Institute War Clauses (Sendings by Post) CL390 (01/03/2009)', false, true, false, false, true, 6, 'Editor.pdf'),
  ('one_off_general', null, 'sanctions', 'Sanctions Clause (EU / Germany / USA)', 'Notwithstanding other provisions of this Open Policy, cover shall be granted only insofar as and as long as not in contradiction to economic, trade or financial sanctions or embargoes enacted by the European Union or the Federal Republic of Germany that are directly applicable to the contracting parties.
This shall also apply to economic, trade or financial sanctions or embargoes enacted by the United States of America, insofar as those are not in contradiction to legislative provisions of the European Union or Germany.', false, false, false, false, true, 5, 'Editor.pdf')
on conflict do nothing;


-- one-time set-up of the Bertling lists (client and its policies); later runs leave staff changes alone
create or replace function public.set_bertling_lists(c bigint) returns void
language plpgsql security definer set search_path = public as $$
declare ed bigint[]; sb bigint[]; pid bigint;
begin
  if exists (select 1 from public.settings where key = 'seed_bertling_lists_r') then return; end if;
  select array_agg(id) into ed from public.clause_library
   where (scope_type = 'one_off_general' and title in ('General Conditions (Open Policy 2009)', 'Air / postal clauses', 'Sanctions Clause (EU / Germany / USA)'))
      or (scope_type = 'customer' and scope_id = c and source = 'Editor.pdf');
  select array_agg(id) into sb from public.clause_library
   where scope_type = 'one_off_general' and source in ('Bertling Open Policy 2009', 'Editor.pdf') and not (id = any(coalesce(ed, '{}')));
  -- client defaults
  update public.customer_clauses x set enabled = false from public.clause_library l
   where x.clause_id = l.id and x.customer_id = c and l.category in ('header','general','sanctions','disclaimer') and not (l.id = any(coalesce(ed, '{}')));
  insert into public.customer_clauses(customer_id, clause_id, enabled) select c, unnest(ed), true on conflict (customer_id, clause_id) do update set enabled = true;
  insert into public.customer_clauses(customer_id, clause_id, enabled) select c, unnest(sb), false on conflict (customer_id, clause_id) do nothing;
  -- its policies
  for pid in select id from public.policies where customer_id = c loop
    update public.policy_clauses x set enabled = false from public.clause_library l
     where x.clause_id = l.id and x.policy_id = pid and l.category in ('header','general','sanctions','disclaimer') and not (l.id = any(coalesce(ed, '{}')));
    insert into public.policy_clauses(policy_id, clause_id, enabled) select pid, unnest(ed), true on conflict (policy_id, clause_id) do update set enabled = true;
    insert into public.policy_clauses(policy_id, clause_id, enabled) select pid, unnest(sb), false on conflict (policy_id, clause_id) do nothing;
  end loop;
  insert into public.settings(key, value, note) values ('seed_bertling_lists_r', 'true', 'Bertling clause lists set up by update r (do not delete)') on conflict (key) do nothing;
end $$;

-- Bertling's own blocks (opening and disclaimer name Bertling)
do $$
declare c bigint;
begin
  select id into c from public.customers where name ilike 'Bertling%' order by id limit 1;
  if c is null then return; end if;
  insert into public.clause_library(scope_type, scope_id, category, title, body, maritime, air_only, default_spot, oneoff_list, active, sort, source) values
    ('customer', c, 'header', 'Opening (Bertling open policy)', 'We thank you for your new enquiry for which we can offer full coverage under Bertling Group''s Open Marine Cargo Policy as per standard policy terms and conditions:', false, false, false, false, true, 1, 'Editor.pdf'),
    ('customer', c, 'disclaimer', 'Title to goods (Bertling)', 'Please note that your client must have title to the goods and must instruct Bertling to arrange for Marine Cargo Insurance prior to commencement of risk.', false, false, false, false, true, 1, 'Editor.pdf')
  on conflict do nothing;
  -- Bertling list: Editor.pdf blocks active, the earlier single clauses on standby, the 67 policy clauses on standby
  perform public.set_bertling_lists(c);
end $$;

-- one-off list: everything that was in the general library so far stays in it; new seeds are library-only (oneoff_list false)
notify pgrst, 'reload schema';
